n.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});	D=org.jsoup.Jsoup.parse(java.ajax("https://m.manhua100.com/category"))
D.select(".category-filter dl").forEach(n=>{
	li=n.select("dd>a")
	push(li.text(),li.attr("href"),1,1)
	n.select(".swiper-wrapper>a").forEach(t=>{
		push(t.text(),`${t.attr("href")}/page/{{page}}`,1,0.25)	
		})
	})
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

